import {accountInput} from './analysis.mjs';
import {verdictExplanationHTML,hasContribution} from './verdict-explanation.mjs?v=plain-1';
import {metricTone,metricIcon} from './metric-style.mjs';
import {rankBadgeHTML} from './rank-badge.mjs?v=viewer-1';
import {enrichCohorts,cohortMetricHTML} from './cohort-comparison.mjs?v=cohort-1';
import {overallReportHTML} from './overall-report.mjs?v=plain-1';
import {avatarHTML,mountAvatar} from './profile-avatar.mjs?v=avatar-1';
import {reassessReport} from './role-analysis.mjs?v=roles-1';
import {detailedReplayHTML,mountReplayDetails} from './replay-details.mjs?v=partial-1';
import {heroPortrait,purchasesHTML,laneMapHTML,fightsHTML,economyHTML,mountReplayVisuals} from './replay-visuals.mjs?v=roles-1';
import {replayFacts} from './replay-view.mjs?v=viewer-1';
import {rememberSearch} from './history.mjs';
import {mountParsing,parsePanelHTML} from './parsing-ui.mjs?v=partial-1';
import { createBrowserScanner } from './browser-scan.mjs?v=partial-1';
import { enrichReport } from './enrichment.mjs?v=sources-1';
const scanPlayer = createBrowserScanner();
document.querySelector('#loading .muted').textContent='Одна неудачная игра или привычка подводить команду? Смотрим на игру в целом — и готовим ответ.';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const publicText=s=>String(s||'').replace(/OpenDota|STRATZ|Dotabuff/gi,'анализа').replace(/IMP/g,'оценки вклада').replace(/lane_pos/g,'Карта позиций').replace(/Уже полученные матчи сохранены\.?|Полученные матчи сохранены\.?|загруженные матчи сохранены\.?/gi,'');
const n=(v,d=0)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—';
const time=s=>`${Math.floor(Math.abs(s)/60)}:${String(Math.floor(Math.abs(s)%60)).padStart(2,'0')}`;
const date=s=>s?new Date(s*1000).toLocaleDateString('ru-RU'):'—';
let current,controller;
const roleNames={CORE:'Кор',SUPPORT:'Поддержка',SOFT_SUPPORT:'Поддержка',HARD_SUPPORT:'Полная поддержка',POSITION_1:'1 · Керри',POSITION_2:'2 · Мидер',POSITION_3:'3 · Офлейнер',POSITION_4:'4 · Поддержка',POSITION_5:'5 · Полная поддержка',SAFE_LANE:'Лёгкая линия',MID_LANE:'Центр',OFF_LANE:'Сложная линия',JUNGLE:'Лес',ROAMING:'Роуминг'};
const roleName=v=>v==null?'—':roleNames[v]||v;
function stratzMatchHTML(s){
  if(!s)return '<h3>Вклад в игру</h3><p class="muted">Дополнительные данные этого матча не получены.</p>';
  return `<h3>Роль и вклад в игру</h3><div class="chips"><span class="chip">Позиция: ${esc(roleName(s.position))}</span><span class="chip">Роль: ${esc(roleName(s.role))}</span><span class="chip">Линия: ${esc(roleName(s.lane))}</span><span class="chip">Оценка вклада: ${n(s.imp)}</span></div><p class="muted">Роль и линия определены автоматически. Положительная оценка вклада — игра лучше ожиданий, отрицательная — хуже. Она не доказывает намеренный руин.</p>${s.impPerMinute?.length?chart(s.impPerMinute,'Оценка вклада по минутам'):''}<details><summary>Смерти и обзор</summary>${s.deaths===null?'<p>Данные смертей из реплея недоступны.</p>':`<div class="table-wrap"><table><thead><tr><th>Время смерти</th><th>Потеря золота</th><th>Время мёртвым, сек.</th><th>Контекст</th></tr></thead><tbody>${s.deaths.map(d=>`<tr><td>${time(d.time)}</td><td>${n(d.goldLost)}</td><td>${n(d.timeDead)}</td><td>${d.isDieBack?'После выкупа. ':''}${d.isAttemptTpOut?'Попытка телепорта. ':''}</td></tr>`).join('')||'<tr><td colspan="4">Событий нет.</td></tr>'}</tbody></table></div>`}<p>Событий установки вардов: ${s.wards===null?'нет данных':n(s.wards.length)}. </p></details>`;
}
function sourcesHTML(r){
  const c=r.sourceComparison;
  if(!hasContribution(r))return ''; 
  return `<section class="report-card"><h2>Как игрок влияет на игру</h2><p>Оценка вклада показывает, насколько удачно игрок действовал относительно ожидаемого уровня игры. <b>Выше нуля — лучше ожиданий, ниже — хуже.</b> Это не процент побед и не доказательство намеренного руина.</p><div class="grid-stats"><div class="stat"><span>Средняя оценка вклада</span><strong>${n(c.mean,1)}</strong><small>Игр с оценкой: ${c.count}. Пропуски не заменяются нулями.</small></div><div class="stat"><span>Лучше / хуже ожиданий</span><strong>${c.positive} / ${c.negative}</strong><small>Количество игр с положительной и отрицательной оценкой. Нулевые оценки не входят в эти группы.</small></div></div><p class="note">${c.count<10?'Пока мало оценённых игр для уверенной сверки. Основной вывод опирается на доступные игровые показатели.':c.disagreement?'Игровые показатели и оценка вклада расходятся. Поэтому итог — «Смешанная картина».':'Оценка вклада дополняет общую картину. Одинаковые убийства и смерти не учитываются повторно.'}</p></section>`;
}
const descriptions={kills:['Убийства','Среднее за матч. Само по себе не определяет полезность.'],deaths:['Смерти','Среднее за матч; контекст и длительность важны.'],assists:['Помощь','Участие в убийствах союзников.'],gold_per_min:['GPM','Золото в минуту. Сильно зависит от роли.'],xp_per_min:['XPM','Опыт в минуту — темп набора уровней.'],hero_damage:['Урон героям','Средний суммарный урон за матч.'],tower_damage:['Урон строениям','Давление на объекты, а не только драки.'],hero_healing:['Лечение','Учтённое лечение за матч.'],last_hits:['Добивания','Число добитых крипов за матч.'],obs_placed:['Обсерверы','Поставленные варды; только доступные разборы.'],sen_placed:['Сентри','Поставленные сентри; не оценка качества обзора.'],camps_stacked:['Стаки лагерей','Созданные стаки по данным реплеев.'],stuns:['Контроль, сек.','Длительность оглушений по доступным событиям.']};
function chart(values,label){if(!Array.isArray(values)||!values.length)return '<p class="muted">Нет временного ряда.</p>';const valid=values.filter(v=>Number.isFinite(v));if(!valid.length)return '';const lo=Math.min(0,...valid),hi=Math.max(1,...valid),span=hi-lo||1;const points=values.map((v,i)=>Number.isFinite(v)?`${10+i/Math.max(1,values.length-1)*580},${145-(v-lo)/span*130}`:null).filter(Boolean).join(' ');return `<svg class="chart" viewBox="0 0 600 160" role="img" aria-label="${esc(label)}"><polyline fill="none" stroke="#d4aa68" stroke-width="2" points="${points}"/></svg><small>${esc(label)} · минимум ${n(Math.min(...valid))}, максимум ${n(Math.max(...valid))}; слева начало, справа конец.</small>`;}
function conclusionHTML(m){const a=m.assessment;return '<section class="replay-summary game-conclusion"><h3>Вывод по игре: '+esc(a.title)+'</h3><p><b>'+esc(a.role.label)+'</b> · '+esc(a.role.basis)+(m.score===null?'':' · Оценка '+n(m.score)+'/100')+'</p><ul>'+a.reasons.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p>'+esc(a.context)+'</p><small>Это оценка доступных показателей, а не всех решений в реплее. Ориентиры по герою; вес зависит от роли. Точного сравнения с игроками той же роли и рейтинга пока нет.</small></section>';}
function matchHTML(m){const p=m.player;return `<details class="match" id="match-${m.matchId}"><summary><b class="${m.win?'win':'loss'}">${m.win===null?'?':m.win?'ПОБЕДА':'ПОРАЖЕНИЕ'}</b>${heroPortrait(m.heroId)}<span class="match-head">${esc(m.hero)} · ${date(m.startTime)}</span><span>${n(p.kills)}/${n(p.deaths)}/${n(p.assists)}</span><small>${time(m.duration)} · ${m.parsed?'Реплей обработан':m.stratz?.parsedAt?'Частичный разбор':'Базовые данные'}</small></summary><div class="match-body">${!m.parsed?'<p class="note">Получена только часть данных этой игры. Карта позиций, тайминги и разбивка урона требуют отдельной обработки реплея. Нажми «Запросить подробности» на карточке этой игры, затем «Проверить готовность». Старый реплей может быть недоступен.</p>':''}${m.parsed||m.stratz?.parsedAt?`<section class="replay-summary"><h3>Разбор игры: ${esc(m.hero)}</h3><ul>${replayFacts(m).map(f=>`<li>${esc(f)}</li>`).join('')}</ul><p class="muted">Это выводы по зафиксированным событиям. Они не устанавливают намерения игрока или единственную причину поражения.</p></section>`:''}<div class="chips"><span class="chip">Матч ${m.matchId}</span><span class="chip">GPM ${n(p.gold_per_min)}</span><span class="chip">XPM ${n(p.xp_per_min)}</span><span class="chip">Участие в убийствах ${n(m.killParticipation)}%</span><span class="chip">${esc(({1:"All Pick",2:"Captains Mode",3:"Random Draft",4:"Single Draft",5:"All Random",22:"Рейтинговый All Pick",23:"Turbo"})[m.mode]||"Другой режим")}</span><span class="chip">${esc(({1:"Лёгкая линия",2:"Центральная линия",3:"Сложная линия",4:"Лес"})[p.lane_role]||"Линия не определена")}</span></div>${m.unavailable?'<p class="note">Подробности матча не получены. В вердикте эта игра не оценивалась.</p>':''}${stratzMatchHTML(m.stratz)}${detailedReplayHTML(m)}<h3>Сравнение по герою</h3><div class="table-wrap"><table><thead><tr><th>Показатель</th><th>Значение</th><th>Процентиль</th></tr></thead><tbody>${m.metrics.map(x=>`<tr><td>${esc(x.label)}</td><td>${n(x.value,1)}</td><td><span>${n(x.percentile)} / 100</span><div class="metric-gauge"><i style="width:${Math.max(0,Math.min(100,x.percentile??0))}%"></i></div></td></tr>`).join('')||'<tr><td colspan="3">Ориентиры недоступны</td></tr>'}</tbody></table></div><small>Процентиль — положение среди игроков на том же герое. Например, 70/100 — выше примерно 70% наблюдений. Рейтинг и роль могут отличаться.</small><h3>Эпизоды для просмотра</h3>${m.events.map(e=>`<div class="event"><b>${time(e.time)} · ${esc(e.title)}</b><p>${esc(e.text)}</p></div>`).join('')||'<p class="muted">По доступным данным подходящих эпизодов не выделено. Это не означает отсутствия ошибок.</p>'}${[m.goldAdvantage,m.xpAdvantage,p.gold_t,p.xp_t].some(a=>a?.some(Number.isFinite))?`<details open><summary>Экономика по ходу игры</summary>${economyHTML(m)}</details>`:''}${Object.keys(p.lane_pos||{}).length?`<details open><summary>Позиции на линии</summary>${laneMapHTML(m)}</details>`:''}<details open><summary>Покупки и тайминги</summary>${purchasesHTML(p)}</details>${m.fights.length?`<details open><summary>Командные драки (${m.fights.length})</summary>${fightsHTML(m)}</details>`:''}${!m.parsed?'<p class="note">Для дополнительных подробностей нажми «Запросить разбор» в блоке «Разборы реплеев». Доступность зависит от сохранности реплея.</p>':''}${conclusionHTML(m)}</div></details>`;}
function render(r){r=reassessReport(r);current=r;$('#loading').hidden=true;const c=r.coverage;$('#report').innerHTML=`<section class="report-card verdict verdict-split ${esc(r.tone)}"><div class="verdict-identity"><span class="eyebrow">ТВОЙ ТИММЕЙТ ПОД ЛУПОЙ</span><h1 class="report-title">${esc(r.verdict)}</h1><p>${esc(publicText(r.description))}</p><div class="profile-row">${avatarHTML(r.profile)}<strong>${esc(r.profile.personaname||`Игрок ${r.accountId}`)}</strong><span class="muted">Dota ID ${r.accountId}</span><a href="https://steamcommunity.com/profiles/${BigInt(r.accountId)+76561197960265728n}" target="_blank" rel="noopener">Steam ↗</a>${rankBadgeHTML(r.rank)}</div><div class="chips"><span class="chip">С разбором реплея: ${r.matches.filter(m=>m.parsed||m.stratz?.parsedAt).length}</span><span class="chip">Победы ${n(r.winrate)}%</span></div></div>${overallReportHTML(r)}</section>${sourcesHTML(r)}<section class="report-card"><h2>Почему такой вывод</h2>${verdictExplanationHTML(r)}<div class="chips">${r.roleSummary.map(g=>`<span class="chip">${esc(g.role)}: ${g.games} игр · ${g.score}/100</span>`).join('')}</div><div class="two-col">${r.comparisons.map(x=>`<div class="benchmark metric-${metricTone(x.label)}"><header><b>${metricIcon(x.label)}${esc(x.label)}</b><span>${n(x.percentile)}/100</span></header><div class="bar"><i style="width:${x.percentile??0}%"></i></div><small>Средний процентиль · игр с данными: ${x.samples}</small></div>`).join('')}</div></section><section class="report-card"><h2>Статистика серии</h2><p class="muted">${r.cohortComparison?.matchedGames?`Сопоставлено ${r.cohortComparison.matchedGames} из ${r.matches.length} игр. Группа рейтинга: ${esc(r.cohortComparison.group)}. Герой и позиция совпадают; ориентир взят на ближайшей минуте к завершению каждой игры. Это текущая недельная выборка, а не точный MMR или исторический патч. Для каждого показателя сравниваются только игры с обеими величинами. Большое значение не всегда означает хорошую игру.`:esc(r.cohortComparison?.reason||'Ориентиры по рейтингу пока недоступны.')}</p><div class="grid-stats">${Object.entries(r.aggregates).map(([k,v])=>`<div class="stat metric-${metricTone(k)}"><span class="metric-label">${metricIcon(k)}${descriptions[k][0]}</span><strong>${n(v.value,1)}</strong><small class="sample-count">Игр с данными: ${v.samples}</small><details class="metric-explanation"><summary>О показателе</summary><small>${descriptions[k][1]}</small></details>${cohortMetricHTML(r.cohortComparison,k)}</div>`).join('')}</div></section><section class="report-card replay-section">${parsePanelHTML()}</section><section class="report-card" id="replay-viewer" hidden><div class="viewer-heading"><h2>Разбор выбранной игры</h2><button id="close-replay" type="button">Закрыть разбор</button></div>${r.matches.map(matchHTML).join('')||'<p>Публичная история не найдена. Это не повод для негативного вердикта.</p>'}</section>`;
$('#close-replay').onclick=()=>{document.querySelector('#replay-viewer').hidden=true;document.querySelector('#parse-list')?.scrollIntoView({block:'start'});};
mountAvatar();
mountReplayVisuals();
mountReplayDetails();
mountParsing(scanPlayer,r,{refresh:start,signal:controller.signal});
}
async function start(){
  controller?.abort();controller=new AbortController();
  $('#failure').hidden=true;$('#loading').hidden=false;$('#report').innerHTML='';
  $('#retry').disabled=true;
  try{
    const input=new URLSearchParams(location.search).get('id');
    if(!input)throw new Error('В адресе нет Steam ID. Вернись на главную и введи профиль.');
    rememberSearch(input);
    const base=await scanPlayer(input,{signal:controller.signal,onProgress:(message,count)=>{
      $('#progress').textContent=count<1?'Собираем историю игр…':count<10?'Изучаем фарм, драки и помощь команде…':'Сопоставляем сильные стороны и повторяющиеся ошибки…';$('#progress-bar').value=count;
    }});
    const enriched=await enrichReport(base,{signal:controller.signal,onProgress:()=>$('#progress').textContent='Сверяем показатели и готовим вердикт…'});
    $('#progress').textContent='Подбираем ориентиры по героям и позициям…';
    const report=await enrichCohorts(enriched,{signal:controller.signal});
    rememberSearch(input,report.profile.personaname);
    render(report);
  }catch(e){
    if(e.name==='AbortError')return;
    $('#loading').hidden=true;$('#failure').hidden=false;$('#failure-text').textContent=e.status===429?'Слишком много запросов. Подожди и попробуй позже.':publicText(e.message);
  }finally{$('#retry').disabled=false;}
}
const quickForm=document.querySelector('#quick-scan');
quickForm.addEventListener('submit',event=>{
 event.preventDefault();const input=document.querySelector('#quick-id'),error=document.querySelector('#quick-error'),value=input.value.trim();
 try{accountInput(value);rememberSearch(value);location.href='./report.html?id='+encodeURIComponent(value);}catch(e){error.textContent=value?e.message:'Введи Steam ID или ссылку на профиль.';input.focus();}
});
document.querySelector('#quick-id').addEventListener('input',()=>document.querySelector('#quick-error').textContent='');
$('#retry').onclick=start;start();
